const item = $input.first();

const pdfText = item.json.text;
const uploadCount = item.json.upload_count || 0;
const isFirstUpload = uploadCount === 0;
const preferredCurrency = item.json.preferred_currency || 'NGN';

const existingMerchants = item.json.merchant_map || [];
const merchantContext = existingMerchants.length > 0
  ? `Known merchants for this user: ${JSON.stringify(existingMerchants)}`
  : 'No prior merchant history — this is the user\'s first upload.';

const prompt = `You are a financial data extraction engine for a Nigerian user.

USER CONTEXT:
- Upload number: ${uploadCount + 1}
- First time user: ${isFirstUpload}
- Currency: ${preferredCurrency}
- ${merchantContext}

Extract every transaction from this bank statement text. Return ONLY a JSON array with no explanation, no markdown, no code fences. Each object must have exactly these fields:
- date (YYYY-MM-DD)
- raw_description (exactly as it appears in the statement)
- amount (positive number, no commas)
- type ("debit" if the amount was negative, "credit" if positive)
- channel (use the Channel column value: NIP, POS, System, E-Channel)
- reference (the Transaction Reference value)
- counterparty (the Counterparty value, or null if not present)

BANK STATEMENT TEXT:
${pdfText}`;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1 }
};

const userId = item.json.id || item.json.user_id || $('Webhook').first().json.body.user_id;

if (!userId) throw new Error('user_id missing from all sources — check Merge output');

return [{
  json: {
    payload,
    user_id: userId,
    upload_id: $('Webhook').first().json.body.upload_id,
    upload_count: uploadCount,
    is_first_upload: isFirstUpload
  }
}];

const item = $input.first();

const rawText = item.json.candidates[0].content.parts[0].text;

let cleaned = rawText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Replace smart apostrophes that break JSON.parse
cleaned = cleaned.replace(/\u2019/g, "'").replace(/\u2018/g, "'");

let transactions;
try {
  transactions = JSON.parse(cleaned);
} catch(e) {
  return [{ json: { error: e.message, previewAt5600: cleaned.substring(5580, 5650) } }];
}

const user_id = $('Prepare Gemini Payload').first().json.user_id;
const upload_id = $('Prepare Gemini Payload').first().json.upload_id;

const enriched = transactions.map(tx => {
  const dateValue = tx.date || null;
  return {
    transaction_date: dateValue,
    raw_description: tx.raw_description || null,
    amount: tx.amount || null,
    type: tx.type || null,
    channel: tx.channel || null,
    reference: tx.reference || null,
    counterparty: tx.counterparty || null,
    merchant_name: null,
    category: null,
    confidence_score: null,
    currency: 'NGN',
    user_id,
    upload_id,
    month_year: dateValue ? dateValue.substring(0, 7) : null,
    created_at: new Date().toISOString()
  };
});

return enriched.map(tx => ({ json: tx }));

const items = $input.all();
const transactions = items.map(item => item.json);

const user_id = transactions[0].user_id;
const upload_id = transactions[0].upload_id;

return [{
  json: {
    user_id,
    upload_id,
    transactions,
    transaction_count: transactions.length
  }
}];

const item = $input.first();
const { patterns } = item.json;

// transactions/user_id/upload_id no longer arrive directly —
// Aggregate Patterns for Story sits between this node and Aggregate for Intelligence now
const intelligenceData = $('Aggregate for Intelligence:').first().json;
const { transactions, user_id, upload_id } = intelligenceData;

// Compute quick stats in JS so Gemini doesn't have to
const debits = transactions.filter(t => t.type === 'debit');
const credits = transactions.filter(t => t.type === 'credit');
const totalSpent = debits.reduce((sum, t) => sum + t.amount, 0);
const totalEarned = credits.reduce((sum, t) => sum + t.amount, 0);

const spendByCategory = {};
debits.forEach(t => {
  const key = t.raw_description;
  spendByCategory[key] = (spendByCategory[key] || 0) + t.amount;
});

const topCategories = Object.entries(spendByCategory)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, amount]) => ({ name, amount }));

// Format detected patterns into readable lines for the prompt
const patternsSummary = patterns.map(p =>
  `- ${p.pattern_type} (${p.pattern_key}): ${JSON.stringify(p.pattern_value)} [confidence: ${p.confidence}]`
).join('\n');

const prompt = `You are a personal finance storyteller for a Nigerian user. Analyze these transactions and the detected behavioral patterns to generate a Spotify Wrapped-style financial story.

STATS:
- Total earned: ₦${totalEarned.toLocaleString()}
- Total spent: ₦${totalSpent.toLocaleString()}
- Net: ₦${(totalEarned - totalSpent).toLocaleString()}
- Transaction count: ${transactions.length}
- Top spending categories: ${JSON.stringify(topCategories)}

DETECTED BEHAVIORAL PATTERNS — reference these directly to make the story personal, not generic:
${patternsSummary}

FULL TRANSACTIONS:
${JSON.stringify(transactions.map(t => ({
  date: t.transaction_date,
  description: t.raw_description,
  amount: t.amount,
  type: t.type,
  channel: t.channel,
  counterparty: t.counterparty
})))}

Return ONLY a JSON object with this exact structure, no markdown, no explanation:
{
  "headline": "one punchy sentence summarizing the period",
  "summary": "2-3 sentence narrative of their financial behaviour",
  "cards": [
    { "type": "income", "title": "...", "value": "...", "insight": "..." },
    { "type": "spending", "title": "...", "value": "...", "insight": "..." },
    { "type": "behaviour", "title": "...", "value": "...", "insight": "..." },
    { "type": "advice", "title": "...", "value": "...", "insight": "..." }
  ],
  "advice_flags": ["flag1", "flag2"],
  "month_year": "2025-01"
}`;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.4 }
};

return [{ json: { payload, user_id, upload_id } }];

const item = $input.first();

const rawText = item.json.candidates[0].content.parts[0].text;
const cleaned = rawText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

const story = JSON.parse(cleaned);

// Pull transactions from upstream — same pattern as Prepare Story Prompt
const intelligenceData = $('Aggregate for Intelligence:').first().json;

return [{
  json: {
    ...story,
    transactions: intelligenceData.transactions || [],
    user_id: intelligenceData.user_id,
    upload_id: intelligenceData.upload_id,
  }
}];

const item = $input.first();

// Story fields are spread directly on item.json, not nested under 'story'
const { user_id, upload_id } = item.json;

// Pull month_year from transactions
const transactions = $('Prepare Classification Payload').first().json.transactions;
const month_year = transactions && transactions.length > 0 ? transactions[0].month_year : null;

// The whole item.json IS the story — exclude non-story fields for storage
const { transactions: _, user_id: __, upload_id: ___, ...storyData } = item.json;

return [{
  json: {
    user_id,
    upload_id,
    month_year,
    story_json: storyData,
    advice_flags: storyData.advice_flags || null,
    patterns_snapshot: null,
    upload_count_at_time: item.json.upload_count || 0,
    is_first_upload: item.json.is_first_upload !== undefined ? item.json.is_first_upload : true
  }
}];

const items = $input.all();
const transactions = items.map((item) => item.json);

return [
  {
    json: {
      transactions,
      transaction_count: transactions.length,
    },
  },
];

const item = $input.first();
const { transactions } = item.json;

// Send only the fields Gemini needs for classification — keeps the prompt lean
const txForClassification = transactions.map((tx, index) => ({
  index,
  raw_description: tx.raw_description,
  counterparty: tx.counterparty,
  amount: tx.amount,
  type: tx.type,
  channel: tx.channel
}));

const prompt = `You are a financial classification engine for a Nigerian user. You will receive an array of bank transactions. For EACH transaction, resolve a clean merchant name and assign a spending category.

CATEGORIES (use exactly one per transaction): food, transport, bills, shopping, subscriptions, income, transfers, fees, airtime_data, entertainment, other

RULES:
- merchant_name: a clean, human-readable name. If raw_description and counterparty give no real clue (e.g. "Account Maintenance", "Stamp Duty"), set merchant_name to the bank/system itself (e.g. "Bank Charges").
- category: "fees" for Account Maintenance, Stamp Duty, and similar bank charges. "income" for Salary Credit, Invoice Settlement, Customer Deposit, Contract Payment when type is credit. "transfers" for generic Transfer to/from Supplier or Client Payment with no specific merchant. "airtime_data" for Airtime Purchase and Data Purchase.
- confidence_score: 0.0 to 1.0 — how sure you are about this classification. Generic/ambiguous descriptions get lower scores (0.4-0.6). Clear matches get high scores (0.85-1.0).

IMPORTANT: 
- merchant_name must never contain apostrophes or single quotes. 
- Replace possessives with alternatives: "Shoprites" not "Shoprite's", "Traders" not "Trader's", "Mamas Kitchen" not "Mama's Kitchen".

TRANSACTIONS:
${JSON.stringify(txForClassification)}

Return ONLY a JSON array, same order, same length as input, no markdown, no explanation. Each object: { "index": number, "merchant_name": string, "category": string, "confidence_score": number }`;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1 }
};

return [{
  json: {
    payload,
    transactions  // pass the full original transactions through for the merge step later
  }
}];

const items = $input.all();
const transactions = items.map(item => item.json);

const user_id = transactions[0].user_id;

const merchantMap = {};
transactions.forEach(tx => {
  // Guard against missing raw_description
  const key = tx.raw_description;
  if (!key) return; // skip transactions with no description

  if (!merchantMap[key]) {
    merchantMap[key] = {
      user_id,
      raw_pattern: key,
      merchant_name: tx.merchant_name || key, // fallback to raw if no merchant resolved
      category: tx.category || 'other',
      occurrence_count: 1
    };
  } else {
    merchantMap[key].occurrence_count += 1;
  }
});

// Filter out any entries that still have null raw_pattern (safety net)
const validEntries = Object.values(merchantMap).filter(m => m.raw_pattern && m.user_id);

return validEntries.map(m => ({ json: m }));

const item = $input.first();
const rawText = item.json.candidates[0].content.parts[0].text;
let cleaned = rawText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

let classifications;

// Attempt 1 — standard parse
try {
  classifications = JSON.parse(cleaned);
} catch(e1) {
  // Attempt 2 — swap curly apostrophes before parsing
  try {
    const s = cleaned.replace(/"((?:[^"\\]|\\.)*)"/g, (m, inner) =>
      '"' + inner.replace(/'/g, '\u2019') + '"'
    );
    classifications = JSON.parse(s);
  } catch(e2) {
    // Attempt 3 — extract array boundaries only
    try {
      const start = cleaned.indexOf('[');
      const end = cleaned.lastIndexOf(']');
      classifications = JSON.parse(cleaned.slice(start, end + 1));
    } catch(e3) {
      throw new Error(`Parse failed at char 5620 area: ${cleaned.substring(5580, 5660)}`);
    }
  }
}

const transactions = $('Prepare Classification Payload').first().json.transactions;
const classificationByIndex = {};
classifications.forEach(c => { classificationByIndex[c.index] = c; });

const enriched = transactions.map((tx, index) => {
  const c = classificationByIndex[index];
  return {
    ...tx,
    merchant_name: c ? c.merchant_name : null,
    category: c ? c.category : 'other',
    confidence_score: c ? c.confidence_score : 0.3
  };
});

return enriched.map(tx => ({ json: tx }));

const item = $input.first();
const { transactions, user_id, upload_id } = item.json;

// Keep the payload lean — only what's needed for pattern detection
const txForPatterns = transactions.map(tx => ({
  date: tx.transaction_date,
  amount: tx.amount,
  type: tx.type,
  category: tx.category,
  merchant_name: tx.merchant_name
}));

const prompt = `You are a financial behavior analysis engine for a Nigerian user. You will receive a full month's (or statement period's) transactions. Detect behavioral patterns across them.

Return ONLY a JSON array, no markdown, no explanation. Each object must have:
- pattern_type: one of "income_signal", "spending_habit", "subscription", "anomaly", "savings_signal"
- pattern_key: a short identifier, e.g. "salary_date", "dominant_category", "avg_monthly_food_spend", "recurring_sub:netflix", "overspending"
- pattern_value: an object with relevant details (amounts, dates, frequency — shape depends on pattern_key)
- confidence: 0.0 to 1.0, how sure you are based on this single statement (one-time signals should be 0.5-0.7, clearly repeating ones 0.8+)

WHAT TO LOOK FOR:
- salary_date: find the credit transaction most likely to be salary (large, regular, labeled "Payroll"/"Salary"). Report typical_day and source.
- dominant_category: which spending category has the highest total debit amount this period.
- recurring subscriptions: any merchant appearing multiple times with similar amounts (subscriptions, airtime plans). One pattern per distinct subscription found.
- overspending: if total debits exceed total credits this period, flag it.
- savings_signal: if there's no transfer to a savings-like destination, note its absence as a low-confidence signal.

Only report patterns you actually find evidence for. Do not invent data.

TRANSACTIONS:
${JSON.stringify(txForPatterns)}`;

const payload = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.1 }
};

return [{
  json: {
    payload,
    user_id,
    upload_id
  }
}];

const item = $input.first();

const rawText = item.json.candidates[0].content.parts[0].text;
const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const patterns = JSON.parse(cleaned);

// Same lesson as before — pull user_id/upload_id from the node that built
// the payload, since the HTTP node's output only contains Gemini's response
const user_id = $('Prepare Patterns Payload').first().json.user_id;

const enriched = patterns.map(p => ({
  user_id,
  pattern_type: p.pattern_type,
  pattern_key: p.pattern_key,
  pattern_value: p.pattern_value,
  confidence: p.confidence
}));

return enriched.map(p => ({ json: p }));

const items = $input.all();
const patterns = items.map(item => item.json);

return [{
  json: {
    patterns
  }
}];

const item = $input.first();
const transactions = item.json.transactions;

// Pull user_id/upload_id from the first transaction (they're the same across all)
const user_id = transactions[0].user_id;
const upload_id = transactions[0].upload_id;

// Build a lightweight version for the prompt — strip fields Gemini doesn't need to see
const transactionsForPrompt = transactions.map((tx, index) => ({
  index,
  raw_description: tx.raw_description,
  counterparty: tx.counterparty,
  amount: tx.amount,
  type: tx.type,
  channel: tx.channel
}));

const prompt = `You are a financial classification engine for Nigerian bank transactions. Below is a list of transactions. For EACH transaction (matched by its "index"), determine:

1. merchant_name — a clean, human-readable merchant or counterparty name (e.g. "DSTV", "Shoprite Lagos", "Salary - XYZ Global"). If it's clearly a peer-to-peer transfer with no merchant, use the counterparty name as-is.
2. category — one of: food, transport, bills, shopping, subscriptions, income, transfers, fees, airtime_data, savings, entertainment, other
3. confidence_score — your confidence in this classification, 0.0 to 1.0

Transactions are often vague bank statement text — use context (amount, channel, counterparty, recurring patterns across the list) to make the best inference.

Return ONLY a JSON array with this exact shape, no explanation, no markdown:
[{"index": 0, "merchant_name": "...", "category": "...", "confidence_score": 0.9}, ...]

TRANSACTIONS:
${JSON.stringify(transactionsForPrompt)}`;

const payload = {
  contents: [
    {
      parts: [
        { text: prompt }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.1
  }
};

return [{
  json: {
    payload,
    transactions, // keep the full original array for merging later
    user_id,
    upload_id
  }
}];

return [{
  json: {
    id: $('Webhook').first().json.body.user_id,
    name: $('Webhook').first().json.body.name || 'New User',
    upload_count: 0,
    first_upload_at: null,
    preferred_currency: 'NGN',
    is_new_user: true
  }
}];

const item = $input.first();
const webhookBody = $("Webhook").first().json.body;
const user_id = webhookBody.user_id;

const existingUser = item.json.id ? item.json : null;

if (existingUser) {
  return [
    {
      json: {
        action: "existing",
        id: existingUser.id,
        name: existingUser.name,
        email: existingUser.email,
        upload_count: existingUser.upload_count || 0,
        first_upload_at: existingUser.first_upload_at,
        preferred_currency: existingUser.preferred_currency || "NGN",
        is_new_user: false,
      },
    },
  ];
}

// New user — pass through for creation
return [
  {
    json: {
      action: "create",
      id: user_id,
      name: webhookBody.name || "New User",
      upload_count: 0,
      first_upload_at: null,
      preferred_currency: "NGN",
      is_new_user: true,
    },
  },
];

const item = $input.first();
return [{
  json: {
    action: 'existing',
    id: item.json.id,
    name: item.json.name || 'New User',
    email: null,
    upload_count: 0,
    first_upload_at: null,
    preferred_currency: 'NGN',
    is_new_user: true
  }
}];
